"use client";

import Link from "next/link";
import {
  Container,
  Grid,
  Typography,
  Card,
  CardContent,
  CardMedia,
  CardActionArea,
} from "@mui/material";
import { useState } from "react";

// Mock des couturiers pour la démonstration
const mockCouturiers = [
  { id: 1, name: "Atelier Élégance", city: "Cotonou", available: "Disponible" },
  { id: 2, name: "Mode Africaine", city: "Porto-Novo", available: "Indisponible" },
  { id: 3, name: "Création Prestige", city: "Parakou", available: "Disponible" },
];

export default function HomePage() {
  const [search, setSearch] = useState("");
  const [city, setCity] = useState("");
  const [availability, setAvailability] = useState("");

  const filtered = mockCouturiers.filter((c) => {
    return (
      c.name.toLowerCase().includes(search.toLowerCase()) &&
      (city ? c.city === city : true) &&
      (availability ? c.available === availability : true)
    );
  });

  return (
    <Container sx={{ py: 8 }}>
      <Typography variant="h4" sx={{ mb: 4 }} textAlign="center">
        Accueil TailleurConnect
      </Typography>

      {/* Liste des cartes */}
      <Grid container spacing={4}>
        {filtered.map((couturier) => (
          <Grid item xs={12} sm={6} md={4} key={couturier.id}>
            <Card>
              {/* CardActionArea rend toute la card cliquable */}
              <CardActionArea component={Link} href={`/couturiers/${couturier.id}`}>
                <CardMedia
                  component="img"
                  height="200"
                  image="https://source.unsplash.com/400x300/?tailor"
                  alt={couturier.name}
                />
                <CardContent>
                  <Typography variant="h6">{couturier.name}</Typography>
                  <Typography color="text.secondary">{couturier.city}</Typography>
                  <Typography
                    color={couturier.available === "Disponible" ? "success.main" : "error.main"}
                  >
                    {couturier.available}
                  </Typography>
                </CardContent>
              </CardActionArea>
            </Card>
          </Grid>
        ))}
      </Grid>

      {filtered.length === 0 && (
        <Typography textAlign="center" sx={{ mt: 5 }}>
          Aucun couturier trouvé.
        </Typography>
      )}
    </Container>
  );
}
